function selectedHistoryPeriod(){const period=selectedPeriod(parseRoute(location.hash),project.viewPeriod,'2025-2026');if(/^\d{4}-\d{4}$/.test(period))return period;if(period.length>=7){const y=Number(period.slice(0,4))-(Number(period.slice(5,7))<10?1:0);return y+'-'+(y+1);}return project.historyPeriod||'2025-2026';}
