function renderCompare(){
 $('house-title').textContent=project.house.name||'Our house';
 $('period-status').textContent=project.consumption?`${number(project.consumption.rows.length)} measured hours imported`:'Hourly consumption integrated';
 const ready=$('readiness');ready.replaceChildren();const title=node('div',undefined,'readiness-title');title.append(node('h2','Build the baseline once. Use it for every proposal.'),node('span','SETUP','eyebrow'));ready.append(title,node('p','Hourly consumption is integrated. Compare household-first estimates; export terms and equipment assumptions still need verification.'));
 const steps=node('div',undefined,'steps');for(const [i,label,destination,done]of [[1,'House & roofs','house',project.house.latitude!==null&&project.house.longitude!==null&&project.house.roofs.every(r=>r.tilt!==null&&r.azimuth!==null)],[2,'Hourly consumption','data',!!project.consumption],[3,'Invoices & tariffs','data',project.tariffs.confirmed],[4,'Proposal specifications','compare',project.proposals.length>0&&project.proposals.every(p=>!missingInputs(project,p).some(s=>/specifications|price/.test(s)))]]){const b=button('',()=>page(destination),'step-link');b.append(node('b',done?'✓':i),document.createTextNode(label));steps.append(b);}ready.append(steps);
 const list=$('proposals');list.replaceChildren();list.setAttribute('aria-busy','false');if(catalogLoading&&!project.proposals.length){list.append(simulationSkeleton('Loading proposals and preparing simulations…'));list.setAttribute('aria-busy','true');return;}if(!project.proposals.length){const empty=node('div',undefined,'empty-state');empty.append(node('span','◫','empty-icon'),node('h2','Start with your first proposal'),node('p','Add a system, assign its panels to the two roofs, then clone it to explore a different configuration.'),button('＋ Create proposal',addProposal,'primary'));list.append(empty);return;}
 renderPaybackComparison(list);

}
const comparisonCache=new Map(),comparisonPending=new Set(),comparisonQueue=[];
let comparisonWorker=null,comparisonBusy=false,comparisonActive=null;const comparisonRestored=new Set();
function queueComparison(key,proposal,dataset){if(comparisonPending.has(key))return;comparisonPending.add(key);loadSimulation('comparison:'+key).catch(()=>null).then(cached=>{if(Number.isFinite(cached?.savings)){comparisonCache.set(key,cached.savings);comparisonRestored.add(key);comparisonPending.delete(key);if(visiblePage==='compare')renderCompare();}else{comparisonQueue.push({key,proposal,dataset});pumpComparison();}});}

function pumpComparison(){if(comparisonBusy||!comparisonQueue.length)return;if(!comparisonWorker){comparisonWorker=new Worker('./comparison-worker.js?v=cash-no-wear',{type:'module'});comparisonWorker.onmessage=({data})=>{comparisonBusy=false;comparisonActive=null;comparisonPending.delete(data.key);comparisonCache.set(data.key,data.error?{error:data.error}:data.savings);if(!data.error)storeSimulation('comparison:'+data.key,{savings:data.savings}).catch(e=>error('Could not cache comparison: '+e.message));if(visiblePage==='compare')renderCompare();pumpComparison();};comparisonWorker.onerror=e=>{comparisonBusy=false;error('Proposal calculation failed: '+e.message);comparisonWorker.terminate();comparisonWorker=null;comparisonPending.clear();comparisonQueue.length=0;};}comparisonBusy=true;const task=comparisonQueue.shift();comparisonActive=task;comparisonWorker.postMessage({...task,project});}
function renderPaybackComparison(list){
 const metric=comparisonMetrics[project.comparisonMetric]?project.comparisonMetric:'payback',controls=node('div',undefined,'tabs comparison-metrics');controls.setAttribute('role','group');controls.setAttribute('aria-label','Compare proposals by');for(const [key,config]of Object.entries(comparisonMetrics)){const b=button(config.label,()=>{project.comparisonMetric=key;save();renderCompare();});b.setAttribute('aria-pressed',String(metric===key));controls.append(b);}list.append(controls);


 if(historyLoadError){list.append(node('p','Could not load simulation data: '+historyLoadError,'pending'));return;}if(historyLoading||historyData.size<3){list.setAttribute('aria-busy','true');list.append(simulationSkeleton('Loading consumption, weather and spot prices for the simulations…'));return;}
 const groups=project.proposals.map(p=>({id:p.id,name:p.name,kind:proposalKind(p),investment:p.cost,installerClaims:p.catalogEvidence?.installerClaims,priceNote:p.catalogEvidence?.priceNote,estimated:p.batteryKwh===0&&p.cost!=null,rows:['2023-2024','2024-2025','2025-2026'].map(period=>{
  const dataset=historyData.get(period),key=optimizationSignature(project,p)+period+dataset.cacheFingerprint;let savings=comparisonCache.get(key);
  if(savings===undefined)queueComparison(key,p,dataset);
  return {period,restored:comparisonRestored.has(key),label:period.slice(0,4)+'–'+period.slice(7),savings:typeof savings==='number'?savings:undefined,years:p.cost!=null&&typeof savings==='number'&&savings>0?p.cost/savings:null,reason:savings===undefined?(comparisonActive?.key===key?'Calculating…':'Queued…'):savings?.error?'Calculation failed':p.cost==null?'Price needed':'No payback'};
 })}));
 const total=groups.reduce((n,g)=>n+g.rows.length,0),complete=groups.flatMap(g=>g.rows).filter(r=>r.reason!=='Calculating…'&&r.reason!=='Queued…').length;
 const status=node('p',complete<total?`Calculating comparisons: ${complete} of ${total} complete (${groups.flatMap(g=>g.rows).filter(r=>r.restored).length} from local cache).${comparisonActive?' Now: '+comparisonActive.proposal.name+' · '+comparisonActive.dataset.period.id+'.':''} You can keep using the app.`:`All ${total} comparisons ready. ${groups.flatMap(g=>g.rows).filter(r=>r.restored).length} loaded from local cache.`,'small');status.setAttribute('role','status');status.setAttribute('aria-live','polite');if(complete<total){status.classList.add('simulation-status');const spinner=node('span',undefined,'simulation-spinner');spinner.setAttribute('aria-hidden','true');status.prepend(spinner);}if(complete<total)list.append(status);list.setAttribute('aria-busy',String(complete<total));
 list.append(paybackChart(groups,(id,period)=>{project.historyPeriod=period;project.viewPeriod=period;save();openProposal(id);},{metric}),node('p',metric==='investment'?'One upfront price per proposal; estimated scenario prices are marked. Click a bar to open the proposal.':'Each bar uses one complete October–September year with the same proposal price and reference invoice tariffs. Tree shading and controller assumptions apply consistently. Click a bar to open that proposal and year.','small'));
 const actions=node('div',undefined,'comparison-proposal-actions');for(const p of project.proposals){const row=node('div',undefined,'card-actions');row.append(routeLink(proposalLabel(p)+' →',{page:'detail',proposalId:p.id,granularity:'monthly'},'open-button'),button('Clone',()=>clone(p.id),'clone-button'));actions.append(row);}list.append(actions);
}
function addProposal(){const p=newProposal(project.house.roofs.length);project.proposals.push(p);save();renderCompare();openProposal(p.id);}
function clone(id){const p=cloneProposal(project.proposals.find(p=>p.id===id));project.proposals.push(p);save();renderCompare();openProposal(p.id);}
$('remove-detail').onclick=()=>{const p=selectedProposal();const b=$('remove-detail');if(b.dataset.confirm!==p.id){b.dataset.confirm=p.id;b.textContent='Click again to remove';return;}project.proposals=project.proposals.filter(item=>item.id!==p.id);selected=null;save();page('compare');};
$('new-proposal').onclick=addProposal;$('clone-detail').onclick=()=>clone(selected);$('back').onclick=()=>page('compare');
function selectedProposal(){return project.proposals.find(p=>p.id===selected);}
function updateDetail(){const p=selectedProposal();try{if(project.consumption&&referenceAligned(project)){const annual=householdBreakdown(householdResult(p),activeReference().key),card=document.querySelector('#page-detail .result-card');card.querySelector('.empty-value').replaceChildren(node('strong',number(annual.savings)),node('span',' SEK / year'));card.querySelector('p:not(.eyebrow)').textContent='Estimated household savings; gap fills are marked in the data view. Contract and battery assumptions remain provisional.';const fields=card.querySelectorAll('.breakdown strong');fields[0].textContent=number(annual.baselineCost-annual.importExpense)+' SEK';fields[1].textContent=number(annual.exportRevenue)+' SEK';fields[2].textContent='Not modelled';fields[3].textContent=p.cost&&annual.savings>0?number(p.cost/annual.savings,1)+' years':'—';}}catch{}renderProposalSwitcher();$('detail-title').replaceChildren();appendProposalName($('detail-title'),p.name,proposalKind(p));renderSolar(p,parseRoute(location.hash).granularity||'monthly');const info=panelSummary(p);$('capacity-summary').textContent=info.kwp!==null?`${info.count} panels × ${number(p.panelWatts)} W = ${number(info.kwp,3)} kWp total. ${info.assigned?'Roof allocation entered.':'Roof allocation still required.'}${info.mismatch?' Allocation differs from total panel count.':''}`:'Panel wattage or count is missing or disputed; see source notes.';const container=$('detail-missing');container.replaceChildren();const missing=missingInputs(project,p);container.append(node('p',missing.length?'Still needed for this proposal:':'Inputs available for the provisional household replay.','small'));if(missing.length){const ul=node('ul',undefined,'missing-list');missing.forEach(s=>ul.append(node('li',s)));container.append(ul);}renderCompare();}

function renderProposalSwitcher(){const bar=$('proposal-switcher');bar.replaceChildren();const index=project.proposals.findIndex(p=>p.id===selected);const granularity=parseRoute(location.hash).granularity||'monthly';const move=offset=>navigate({page:'detail',proposalId:project.proposals[(index+offset+project.proposals.length)%project.proposals.length].id,granularity});const prev=button('← Previous',()=>move(-1));const next=button('Next →',()=>move(1));prev.disabled=next.disabled=project.proposals.length<2;const label=node('label','Proposal');const select=node('select');select.setAttribute('aria-label','Switch proposal');for(const p of project.proposals){const option=node('option',proposalLabel(p));option.value=p.id;option.selected=p.id===selected;select.append(option);}select.onchange=()=>navigate({page:'detail',proposalId:select.value,granularity});label.append(select);bar.append(prev,label,next);}
function renderProposal(id){$('remove-detail').textContent='Remove proposal';delete $('remove-detail').dataset.confirm;selected=id;const p=selectedProposal();const form=$('proposal-form');form.replaceChildren();const kindLabel=node('label','Type'),kindSelect=node('select');kindSelect.setAttribute('aria-label','Proposal type');for(const kind of ['proposal','scenario']){const option=node('option',kind==='proposal'?'Proposal':'Scenario');option.value=kind;option.selected=proposalKind(p)===kind;kindSelect.append(option);}kindSelect.onchange=()=>{p.kind=kindSelect.value;save();updateDetail();};kindLabel.append(kindSelect);form.append(kindLabel);const definitions=[['name','Proposal name','text'],['cost','Total price after deduction · SEK'],['batteryModel','Quoted battery model','text'],['batteryType','Battery chemistry / type','text'],['inverterModel','Quoted inverter model','text'],['panelCount','Total number of panels','number',0,20000],['panelWatts','Power per panel · W'],['inverterKw','Inverter AC power · kW'],['batteryKwh','Usable battery capacity · kWh'],['chargeKw','Battery charge limit · kW'],['dischargeKw','Battery discharge limit · kW'],['roundTripEfficiency','Round-trip efficiency · %','number',1,100],['reservePercent','Minimum battery reserve · %','number',0,99]];for(const [key,label,type='number',min=0,max=1e8]of definitions)field(form,{name:key,label,type,value:p[key],min,max,step:key==='panelCount'?1:'any',required:key==='name'},v=>{p[key]=v;save();updateDetail();});const allocations=$('allocation-form');allocations.replaceChildren();project.house.roofs.forEach((r,i)=>field(allocations,{name:`panels-${i}`,label:`${r.name} · number of panels`,value:p.panels[i],step:1,max:10000},v=>{p.panels[i]=v;save();updateDetail();}));$('proposal-notes').value=p.notes;$('proposal-notes').oninput=e=>{p.notes=e.target.value;save();};renderEvidence(p);updateDetail();showPage('detail');}
function renderConsumption(){const container=$('consumption-summary');container.replaceChildren();if(!project.consumption){container.append(node('p','Greenely consumption export still needs to be added to the project.','pending'));return;}const data=simulationProject().consumption,rows=data.rows,estimated=rows.filter(r=>r.estimated),box=node('div',undefined,'summary-data');box.append(node('strong',`${number(rows.reduce((a,r)=>a+r.kwh,0),2)} kWh over the selected October–September year`),node('p',`${rows.length} hourly intervals: ${rows.length-estimated.length} measured and ${estimated.length} estimated.`),node('p','Estimated hours use same-weekday/hour historical profiles; the November 2025 gap is scaled to its invoice residual (111.77 kWh). Original CSV readings and blanks are preserved. Existing Greenely smart charging remains in the measured baseline.','small'));if(!project.tariffs.invoiceReference){container.append(box);return;}const ref=activeReference(),period=currentPeriod(),level=period===ref.key||period.length===4?'year':period.length===7?'month':'day',groups=new Map();for(const r of rows.filter(r=>periodIncludes(r.time,period,ref))){const key=level==='year'?localStamp(r.time).slice(0,7):level==='month'?localStamp(r.time).slice(0,10):r.time;if(!groups.has(key))groups.set(key,{key,measured:0,estimated:0});groups.get(key)[r.estimated?'estimated':'measured']+=r.kwh;}const points=[...groups.values()];box.append(timeChart({title:'Household electricity use',labels:points.map(r=>level==='year'?monthLabel(r.key):level==='month'?String(Number(r.key.slice(8))):localStamp(r.key).slice(11,16)),unit:'kWh',series:[{name:'Total consumption',values:points.map(r=>r.measured+r.estimated)}],onSelect:level==='day'?null:i=>{project.viewPeriod=points[i].key;save();renderDateNavigation();renderConsumption();}}));const details=node('details');details.append(node('summary','Source and invoice reconciliation'),node('p',data.timestampBasis||project.consumption.timestampBasis,'small'));for(const m of data.invoiceReconciliation??[])details.append(node('p',`${m.month}: observed ${number(m.observedKwh,2)} kWh; invoice ${number(m.invoiceKwh,2)} kWh; difference ${number(m.differenceKwh,2)} kWh${m.missingHours?' before filling '+m.missingHours+' hours':''}.`,'small'));box.append(details);container.append(box);}

$('tariff-notes').value=project.tariffs.notes;$('tariff-notes').oninput=e=>{project.tariffs.notes=e.target.value;save();};
$('eagerness').value=project.strategy.eagerness;const eagerness=()=>{$('eagerness-value').textContent=`${project.strategy.eagerness} / 100`;};eagerness();$('eagerness').oninput=e=>{project.strategy.eagerness=Number(e.target.value);eagerness();save();};
