function renderEvidence(p){
 const box=$('proposal-evidence');box.replaceChildren();
 if(!p.catalogEvidence){box.hidden=true;return;}box.hidden=false;
 const evidence=p.catalogEvidence;if(p.batteryKwh===0){box.append(node('h2','Solar-only scenario'),node('p','Derived from the original proposal. Same solar layout and inverter rating; standalone inverter compatibility needs supplier confirmation.','small'));for(const note of p.notes.split('\n'))box.append(node('p',note,'pending'));return;}
 box.append(node('h2','Battery model & type'));const identity=node('dl',undefined,'hardware-specs');for(const [label,value]of [['Quoted battery',p.batteryModel||evidence.quotedBatteryModel||'Not specified'],['Chemistry',p.batteryType||evidence.batteryChemistry||'Not established'],['Quoted inverter',p.inverterModel||evidence.quotedInverterModel||'Not specified']]){identity.append(node('dt',label),node('dd',value));}box.append(identity);
 box.append(node('p',evidence.originalQuoteAccess?.status==='not_retrieved'?'Original 2026 PDF awaiting verification. Values currently come from the comparison sheet and prior project chat.':evidence.originalQuoteAccess?.status==='verified'?'Original PDF checked: quoted components, price and deduction verified. Missing technical specifications are listed below.':'Imported from the structured catalog. Source discrepancies remain flagged below.'));
 if(p.reportedBatteryKwh!=null)box.append(node('p',`Quoted battery capacity: ${number(p.reportedBatteryKwh,2)} kWh. ${p.batteryKwh==null?'Usable capacity remains unverified.':`Usable capacity entered: ${number(p.batteryKwh,2)} kWh.`}`,'small'));
 if(evidence.allocationStatus==='user_assumption_source_confirmation_required')box.append(node('p',`Panel split assumed: ${p.panels[1]} WNW + ${p.panels[0]} SSW. Double-check against the supplier source.`,'pending'));
 if(evidence.batteryChemistry)box.append(node('p',`Battery chemistry: ${evidence.batteryChemistry}.`,'small'));else if(evidence.batteryTechnologyFamily)box.append(node('p',`Battery family: ${evidence.batteryTechnologyFamily} (user reported). Specific chemistry remains unverified.`,'small'));
 if(p.monthlyFee!=null)box.append(node('p',`Quoted recurring fee: ${number(p.monthlyFee)} SEK/month. Whether this is an additional cost relative to your existing contract remains unverified.`,'small'));
 if(evidence.priceDeductionBasisVerified)box.append(node('p','The PDF explicitly uses a 50,000 SEK deduction. Personal tax eligibility is not independently assessed.','small'));
 if(evidence.batteryModuleMatchConfirmed===false)box.append(node('p',evidence.manufacturerResearch?`Model match: ${evidence.manufacturerResearch.model_match_status}. Exact supplied SKU/configuration still needs confirmation.`:'Provisional battery match: quoted 9 kWh → BAT 10.0. Confirm exact module and included BC controller.','pending'));
 if(evidence.batteryPowerBasis)box.append(node('p',evidence.batteryPowerBasis,'small'));
 if(!evidence.priceEligibilityVerified&&!evidence.priceDeductionBasisVerified)box.append(node('p','Price after deduction still needs confirmation for the household’s eligibility.','pending'));
 for(const conflict of evidence.conflicts){box.append(node('p',`${conflict.field}: ${conflict.alternatives.map(a=>`${a.value} (${a.source_id})`).join(' vs ')}. ${conflict.reason}`,'pending'));}
 if(evidence.manufacturerResearch){const research=evidence.manufacturerResearch;box.append(node('h2','Manufacturer specifications'));const specs=node('dl',undefined,'hardware-specs');for(const [label,value]of [['Matched battery',research.researched_battery_model],['Matched inverter',research.inverter_model],['Module count',`${research.module_count} (inferred from quote)`],['Usable energy',research.usable_energy_kwh!=null?`${number(research.usable_energy_kwh,2)} kWh, conditional on model match`:research.usable_energy_alternatives?`${research.usable_energy_alternatives.map(a=>number(a.three_module_total_kwh,1)).join(' vs ')} kWh · conflicting official documents`:'Not established'],['Grid charging / export','Documented hardware capability; contract and commissioning limits still apply'],['AC round-trip efficiency','Not established; inverter efficiency is a different metric']])specs.append(node('dt',label),node('dd',value));box.append(specs);if(research.physical){const physical=research.physical;box.append(node('h2','Dimensions & volume'),node('p','Width × height × depth · mm. Volume is the enclosing box, not installation space.','small'),node('p',physical.arrangement,'small'));const sizes=node('dl',undefined,'hardware-specs');for(const item of physical.items){sizes.append(node('dt',item.label),node('dd',`${item.width_mm} × ${item.height_mm} × ${item.depth_mm} mm · ${number(item.envelope_volume_litres,1)} L (${number(item.envelope_volume_litres/1000,3)} m³). ${item.status}. ${item.note}`));}box.append(sizes);if(physical.estimated_stack_height_range_mm)box.append(node('p',`With base, estimated stack: 695 × ${physical.estimated_stack_height_range_mm.join('–')} × 170 mm · ${physical.estimated_stack_volume_range_litres.map(v=>number(v,1)).join('–')} L. ${physical.estimate_note}`,'small'));box.append(node('p','Follow up: confirm complete installed assembly dimensions, included base/covers and mounting clearances with the supplier.','pending'));}const researchDetails=document.createElement('details');researchDetails.append(node('summary','Research findings and manufacturer sources'));for(const finding of research.findings)researchDetails.append(node('p',finding,'small'));for(const source of research.sources??[]){const link=node('a',source.title,'source-link');link.href=source.url;link.target='_blank';link.rel='noopener noreferrer';researchDetails.append(link);}box.append(researchDetails);}
 if(evidence.layoutImage){const image=document.createElement('img');image.src=`./data/${evidence.layoutImage}`;image.alt='Svea design: six panels on WNW roof, six on SSW roof';image.style.cssText='display:block;width:100%;border-radius:6px;margin-top:16px';box.append(image,node('p','Quote layout: 6 WNW + 6 SSW panels. Bearings: 289 and 199 degrees. SSW tilt 15 degrees; WNW approximately 38 degrees from the drawing.','small'));}
 const details=document.createElement('details');details.append(node('summary','Original source follow-ups'));
 const list=node('ul',undefined,'missing-list');for(const item of evidence.missingInputs)list.append(node('li',item.follow_up));details.append(list);box.append(details,node('p','Source flags describe the original quote. Entering an override does not mark the original document as verified.','small'));
}
async function loadPresets(){try{const response=await fetch('./data/proposals.json',{cache:'no-store'});if(!response.ok)throw Error('Catalog could not be loaded.');const catalog=await response.json();const merged=mergeCatalog(project,catalog);project=merged.project;if(merged.added||merged.updated||merged.removed)save();renderCompare();}catch(e){error(`Proposal presets unavailable: ${e.message}`);}}
await loadPresets();catalogLoading=false;renderCompare();
try{const response=await fetch('./data/house.json',{cache:'no-store'});if(!response.ok)throw Error('House reference unavailable.');const result=mergeHouseReference(project,await response.json());project=result.project;if(result.changed)save();renderHouse();renderCompare();}catch(e){error(e.message);}

