function renderEnvironment(){const box=$('environment-summary');box.replaceChildren();box.append(node('p',environmentStatus(simulationProject()),'pending'));const e=simulationProject().environment;if(!e)return;const gaps=Object.values(e.series).reduce((sum,series)=>sum+(series.gapFills?.length||0),0);if(gaps)box.append(node('p',`${gaps} missing satellite readings filled from ERA5, with timestamps and source retained.`,'pending'));box.append(node('p',`${e.start} to ${e.end}: ${number(e.series.weather.rows.length)} UTC hours; updated ${e.fetchedAt.slice(0,10)}`));const rows=e.series.weather.rows;box.append(node('p',`Temperature ${number(Math.min(...rows.map(r=>r.temperature_2m)),1)} to ${number(Math.max(...rows.map(r=>r.temperature_2m)),1)} Celsius; wind, cloud cover, precipitation, snowfall and ground snow depth retained.`,'small'));const dl=node('dl',undefined,'hardware-specs');for(const roof of project.house.roofs){const series=e.series[roof.id];const ready=series&&e.signature===environmentSignature(project.house);dl.append(node('dt',roof.name),node('dd',ready?`${number(series.rows.reduce((sum,r)=>sum+r.global_tilted_irradiance/1000,0),1)} kWh/m2 solar energy over this period; ${roof.tilt} degrees tilt${roof.tiltSource?.startsWith('Approximately')?' (drawing estimate)':''}, ${roof.azimuth} degrees bearing`:'Pending roof geometry or automatic data refresh.'));}box.append(dl);const details=node('details');details.append(node('summary','Data sources & modelling limits'));for(const text of e.limitations)details.append(node('p',text,'small'));for(const source of e.sources)details.append(node('p',source.key+' source: Open-Meteo API','small'));box.append(details);}
renderEnvironment();

