function renderSolar(p,granularity='monthly'){
 const box=$('solar-results');box.replaceChildren(node('h2','Modelled solar generation'));let result;try{result=cachedCalculation('solar',p);}catch(e){box.append(node('p',e.message,'pending'));return;}
 box.append(node('p',calculated.source(result)==='saved'?'Loaded saved solar simulation.':'Solar simulation calculated and cached.','small'));
 box.append(node('p',`${number(result.totalKwh)} kWh AC over ${result.start} to ${result.end} (${number(result.hours)} hours)`),node('p',`Peak hourly-average output: ${number(result.peakKw,2)} kW. Estimated clipping: ${number(result.clippedKwh,1)} kWh. This is solar generation, not savings or battery output.`,'small'));
 if(p.catalogEvidence?.allocationStatus==='user_assumption_source_confirmation_required')box.append(node('p',`Egna allocation assumption: ${p.panels[1]} WNW + ${p.panels[0]} SSW. Double-check with the supplier source.`,'pending'));
 box.append(node('p','WNW pitch is a drawing estimate. Tree and western horizon shading use approximate house settings. Panel snow coverage is excluded. Ground snow depth is not treated as panel coverage.','small'));
 for(const roof of result.roofTotals)box.append(node('p',`${roof.name}: ${number(roof.kwh)} kWh AC`,'small'));
 const period=currentPeriod(),ref=activeReference(),rows=result.rows.filter(r=>periodIncludes(r.time,period,ref)),level=period===ref.key||period.length===4?'year':period.length===7?'month':'day',groups=new Map();for(const r of rows){const key=level==='year'?localStamp(r.time).slice(0,7):level==='month'?localStamp(r.time).slice(0,10):r.time;if(!groups.has(key))groups.set(key,{key,roofKwh:r.roofKwh.map(()=>0),acKwh:0});const g=groups.get(key);g.acKwh+=r.acKwh;r.roofKwh.forEach((v,i)=>g.roofKwh[i]+=v);}const points=[...groups.values()];box.append(timeChart({title:'Solar generation',labels:points.map(r=>level==='year'?monthLabel(r.key):level==='month'?String(Number(r.key.slice(8))):localStamp(r.key).slice(11,16)),unit:'kWh',series:result.roofTotals.map((r,i)=>({name:r.name,values:points.map(v=>v.roofKwh[i])})),onSelect:level==='day'?null:i=>{project.viewPeriod=points[i].key;save();renderDateNavigation();renderSolar(p,granularity);}}));
 const a=result.settings;box.append(node('p',`Assumptions: temperature coefficient ${a.temperatureCoefficientPct}%/C; inverter efficiency ${a.inverterEfficiencyPct}%; other DC losses ${a.otherLossPct}%; Faiman U0 ${a.u0}, U1 ${a.u1}. Edit shared assumptions under Data & tariffs. Historical weather is used for this production estimate, not as a battery forecast.`,'small'));

}
const solarForm=$('solar-assumptions');for(const [name,label,min,max]of [['temperatureCoefficientPct','Power temperature coefficient (% per Celsius)',-1,0],['inverterEfficiencyPct','Inverter conversion efficiency (%)',1,100],['otherLossPct','Other DC losses (%)',0,100],['u0','Faiman U0 (thermal assumption)',1,100],['u1','Faiman U1 (wind cooling assumption)',0,50]])field(solarForm,{name,label,value:solarSettings(project.solarModel)[name],min,max},value=>{if(value===null)return;project.solarModel={...solarSettings(project.solarModel),[name]:value};save();renderCompare();if(selected)renderSolar(selectedProposal(),parseRoute(location.hash).granularity);});
if(selected)renderSolar(selectedProposal(),parseRoute(location.hash).granularity);

