function renderPrices(){const box=$('prices-summary');box.replaceChildren();const context=simulationProject(),p=context.prices;if(!p){box.append(node('p','No electricity price data downloaded.','pending'));return;}const values=p.hourly.map(r=>r.sekPerKwh);box.append(node('p',`${p.area}: ${p.start} to ${p.end}; ${number(p.hourly.length)} hourly prices, ${number(p.intervals.length)} source intervals.`),node('p',`Spot price excl. VAT and fees: mean ${number(values.reduce((a,b)=>a+b,0)/values.length,3)}, minimum ${number(Math.min(...values),3)}, maximum ${number(Math.max(...values),3)} SEK/kWh. ${values.filter(v=>v<0).length} negative-price hours.`,'small'));if(context.environment&&(p.start!==context.environment.start||p.end!==context.environment.end))box.append(node('p','Price period differs from weather/solar period. Automatic alignment is pending.','pending'));if(context.consumption){const times=new Set(p.hourly.map(r=>Date.parse(r.time)));if(!context.consumption.rows.every(r=>times.has(Date.parse(r.time))))box.append(node('p','Prices do not cover all consumption hours.','pending'));}const weeks=(weeklyPriceData?.periods[selectedHistoryPeriod()]||[]).filter(w=>currentPeriod()===activeReference().key||(localStamp(w.start).slice(0,currentPeriod().length)<=currentPeriod()&&localStamp(w.end-1).slice(0,currentPeriod().length)>=currentPeriod()));const weekLabel=w=>{const start=new Date(w.start).toLocaleDateString('en-GB',{timeZone:'Europe/Stockholm',day:'numeric',month:'short'}),end=new Date(w.end-1).toLocaleDateString('en-GB',{timeZone:'Europe/Stockholm',day:'numeric',month:'short'});return start+'–'+end;};const priceChart=timeChart({title:'Weekly average spot price',labels:weeks.map(weekLabel),unit:'SEK/kWh',decimals:3,series:[{name:'SE4 spot excl. VAT and fees',values:weeks.map(w=>w.sekPerKwh)}]});if(p.corrections?.length)box.append(node('p',`${p.corrections.length} source timestamp correction retained in the project: DST end boundary corrected using the following interval start.`,'small'));box.append(priceChart,node('p','Weekly means are precomputed time averages for Monday–Sunday, not consumption-weighted bills. Weeks at the reference-year boundaries cover only the available days. A month view includes overlapping weeks. Household dispatch uses source spot prices at 15-minute intervals, with hourly consumption and solar spread evenly within each hour. Older hourly prices are repeated across quarters. Bare spot export compensation is assumed for Greenely; source prices are from Elprisetjustnu.se.','small'));}
let pricesLoading=false;
async function ensurePrices(){if(pricesLoading||!project.environment)return;const {start,end}=project.environment;if(project.prices?.start===start&&project.prices?.end===end)return;pricesLoading=true;try{const prices=await fetchPrices(start,end,{onProgress:text=>$('prices-progress').textContent=text.replace('Downloading','Loading')});project.prices=prices;const saved=save();$('prices-progress').textContent=saved?'SE4 prices are integrated and saved with this simulation.':'Prices loaded for this session; browser storage is full.';renderPrices();if(visiblePage==='strategy')renderArbitrage();if(selected)renderSolar(selectedProposal(),parseRoute(location.hash).granularity);}catch(e){$('prices-progress').textContent=`Price loading failed: ${e.message}. Existing prices kept.`;const retry=button('Retry loading prices',()=>{retry.remove();ensurePrices();});$('prices-summary').append(retry);}finally{pricesLoading=false;}}
renderPrices();

ensurePrices();

function renderInvoices(){const box=$('invoice-summary');box.replaceChildren();const ref=project.tariffs.invoiceReference;if(!ref){box.append(node('p','Invoice extraction is not loaded yet.','pending'));return;}box.append(node('p',`${ref.invoice_count} invoices checked: ${ref.period.start} to ${ref.period.end}. All 12 months covered.`),node('p',`Billed consumption: ${number(ref.summary.consumption_kwh,2)} kWh. Greenely paid: ${number(ref.summary.greenely_paid_sek)} SEK; network paid: ${number(ref.summary.network_paid_sek)} SEK. Invoice totals include VAT and fixed charges; they are not simulated savings.`,'small'));const selectedMonths=ref.monthly.filter(m=>currentPeriod().length===4?m.month.startsWith(currentPeriod()):currentPeriod().length===9?true:m.month===currentPeriod().slice(0,7));const labels=selectedMonths.map(m=>monthLabel(m.month));box.append(timeChart({title:'Monthly billed household consumption',labels,unit:'kWh',series:[{name:'Greenely',values:selectedMonths.map(m=>m.greenely_kwh)}]}),timeChart({title:'Monthly variable import charges',labels,unit:'SEK/kWh',decimals:4,step:true,series:[{name:'Supplier fees',values:selectedMonths.map(m=>m.supplier_variable_sek_per_kwh_ex_vat*1.25)},{name:'Network transfer',values:selectedMonths.map(m=>m.network_transfer_sek_per_kwh_ex_vat*1.25)},{name:'Energy tax',values:selectedMonths.map(m=>m.energy_tax_sek_per_kwh_ex_vat*1.25)}]}),node('p','Variable charges: SEK/kWh including 25% VAT, excluding spot price. Greenely monthly averages are retained; invoice spot averages are not used in place of hourly market prices.','small'),node('p','Fixed fees and annual levies are retained as baseline costs. No demand-charge line appears in these invoices. Export compensation, future tariff applicability and each proposal contract remain unverified.','pending'));if(project.environment&&!referenceAligned(project))box.append(node('p','Weather fetches include surrounding UTC hours to cover the Swedish invoice year. Household savings are trimmed to the invoice-year boundaries.','pending'));const details=node('details');details.append(node('summary','Invoice checks and remaining inputs'));for(const note of [...ref.interpretation,...ref.missing_inputs])details.append(node('p',note,'small'));box.append(details);}
