 const reference=referenceWindow(project.tariffs.invoiceReference),period=currentPeriod(),isReference=period===reference.key,year=period.slice(0,4),go=value=>navigate({page:'strategy',period:value});box.append(node('h2',`${number(view.net,2)} SEK after grid energy costs`),node('p',`${number(view.incremental,2)} SEK versus selling solar immediately (${number(view.baseline,2)} SEK over the same hours).`),node('p',`${isReference?'Full invoice year: 1 October 2025 – 30 September 2026':period+' (Swedish calendar view)'} · ${view.rows.length} simulated intervals. ${!isReference&&period.length===4?'Only the months inside the invoice year are included.':''}`,'small'),node('p','Export-only simulation. Household protection awaits consumption data; these are not household savings or operating instructions.','pending'));
 box.append(node('p',`${full.settings.capacityKwh} kWh · ${full.settings.reservePct}% reserve · ${full.settings.roundTripEfficiencyPct}% efficiency. Provisional assumptions; details below.`,'pending'));
