 const points=view.points,labels=points.map(p=>view.level==='year'?monthLabel(p.key):view.level==='month'?String(Number(p.key.slice(8))):localStamp(p.key).slice(11,16));const inspection=node('div',undefined,'hour-calculation');inspection.setAttribute('aria-live','polite');const inspect=index=>{const r=view.rows[index];inspection.replaceChildren(node('h3',`${r.time.slice(0,16)} UTC`),node('p',`Grid charge ${number(r.gridChargeKwh,3)} kWh × ${number(r.importPrice,4)} SEK/kWh incl. VAT/fees = ${number(r.importExpense,3)} SEK import cost.`),node('p',`Solar charge ${number(r.solarChargeKwh,3)} kWh; battery export ${number(r.dischargeKwh,3)} kWh; total export ${number(r.exportKwh,3)} kWh × ${number(r.spot,4)} spot = ${number(r.exportRevenue,3)} SEK.`),node('p',`Battery export ${number(r.batteryExportKwh??0,3)} kWh. Stored energy ${number(r.startingSocKwh,3)} → ${number(r.socKwh,3)} kWh.`),node('strong',`${number(r.net,3)} SEK net; immediate-solar baseline ${number(r.baseline,3)} SEK.`));};const drill=i=>view.level==='day'?inspect(i):go(points[i].key);
 box.append(node('p',view.level==='day'?'Click an hour for its energy and cash ledger.':'Click a month, then a day, to inspect the strategy.','drill-hint'),timeChart({title:'Cash flow and spot price',labels,unit:'SEK',rightUnit:'SEK/kWh',series:[{name:'Strategy after grid costs',values:points.map(p=>p.net)},{name:'Immediate solar export',values:points.map(p=>p.baseline)},{name:view.level==='day'?'SE4 spot':'Mean SE4 spot',axis:'right',decimals:4,values:points.map(p=>p.spot)}],onSelect:drill}),timeChart({title:'Battery energy flows',labels,unit:'kWh',series:[{name:'Solar charging',values:points.map(p=>p.solarChargeKwh)},{name:'Grid charging',values:points.map(p=>p.gridChargeKwh)},{name:'Battery discharge',values:points.map(p=>p.dischargeKwh)}],onSelect:drill}),timeChart({title:view.level==='day'?'Stored energy at hour end':'Stored energy at period end',labels,unit:'kWh',series:[{name:'State of charge',values:points.map(p=>p.socKwh)},{name:'Minimum reserve',values:points.map(()=>full.settings.capacityKwh*full.settings.reservePct/100)}],onSelect:drill}));if(view.level==='day'){inspect(0);box.append(inspection);}
