async function ensureArchivedForecasts(start,end){const signature=environmentSignature(project.house);if(forecastsLoading||forecastArchive?.signature===signature&&forecastArchive.start===start&&forecastArchive.end===end)return;forecastsLoading=true;try{const house=structuredClone(project.house);const archiveKey='forecast-archive-v1:'+signature+':'+start+':'+end;let archive=await loadSimulation(archiveKey).catch(()=>null);if(!archive){archive=await loadForecasts(house,start,end,text=>{forecastStatus=text;if($('forecast-status'))$('forecast-status').textContent=text+'; persistence baseline shown while loading.';});await storeSimulation(archiveKey,archive).catch(()=>{});}if(signature!==environmentSignature(project.house))throw Error('Roof geometry changed while forecasts loaded.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(archive)));forecastArchive={...archive,start,end,cacheFingerprint:Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('')};forecastStatus=`Archived ECMWF forecasts loaded (${archive.runs.length} daily runs). ${archive.partialRoofRuns.length} roof forecast horizons contain fewer than 48 valid hours; missing targets use persistence. Eight-hour availability lag assumed.`;if(visiblePage==='strategy')renderArbitrage();if(visiblePage==='compare')renderCompare();if(visiblePage==='roi')renderRoi();if(visiblePage==='maximum')renderMaximum();if(visiblePage==='detail'&&selected)updateDetail();}catch(e){forecastStatus='Archived forecasts unavailable: '+e.message+'; previous-day persistence remains active.';if($('forecast-status'))$('forecast-status').textContent=forecastStatus;}finally{forecastsLoading=false;}}

async function ensureReferenceYear(){if(referenceLoading||!project.tariffs.invoiceReference)return;referenceLoading=true;const w=referenceWindow(project.tariffs.invoiceReference);try{$('environment-start').value=w.startDate;$('environment-end').value=w.endDate;referenceLoadStatus='Loading weather and sunlight for the full invoice year...';await ensureEnvironment();if(!referenceAligned(project))await ensurePrices();if(referenceAligned(project)){if(visiblePage==='strategy'&&(!parseRoute(location.hash).period||parseRoute(location.hash).period.length===4))navigate({page:'strategy',period:w.key},{replace:true});else if(visiblePage==='strategy')renderArbitrage();}}finally{referenceLoading=false;}}
let calculationWorker=null,calculationSequence=0;const calculationRequests=new Map();
function runCalculation(input){if(!calculationWorker){calculationWorker=new Worker('./calculation-worker.js?v=cash-no-wear',{type:'module'});calculationWorker.onmessage=({data})=>{const request=calculationRequests.get(data.id);if(!request)return;calculationRequests.delete(data.id);data.error?request.reject(Error(data.error)):request.resolve(data.result);};calculationWorker.onerror=e=>{for(const request of calculationRequests.values())request.reject(Error(e.message||'Calculation worker failed.'));calculationRequests.clear();calculationWorker.terminate();calculationWorker=null;};}return new Promise((resolve,reject)=>{const id=++calculationSequence;calculationRequests.set(id,{resolve,reject});calculationWorker.postMessage({id,...input});});}
const calculated=createCalculationCache({load:loadSimulation,store:storeSimulation,compute:runCalculation,onReady:()=>{if(['roi','strategy','detail'].includes(visiblePage))applyRoute();},onError:e=>error('Could not save calculation cache: '+e.message)});
function cachedCalculation(kind,proposal){if(historyLoading)throw Error('Loading simulation inputs and saved calculations…');const context=simulationProject(),oldYear=selectedHistoryPeriod()!=='2025-2026',archive=kind!=='solar'&&!oldYear&&forecastArchive?.signature===environmentSignature(context.house)?forecastArchive:null;
 const hardware={panels:proposal.panels,panelCount:proposal.panelCount,panelWatts:proposal.panelWatts,inverterKw:proposal.inverterKw};
 const key=JSON.stringify({model:'calculations-v5-cash-no-wear',kind,period:selectedHistoryPeriod(),source:historyData.get(selectedHistoryPeriod())?.cacheFingerprint,house:context.house,solarModel:context.solarModel,hardware,battery:kind==='solar'?null:batterySettings(context,proposal),consumption:kind==='solar'?null:[context.consumption?.revision,context.consumption?.rows.length],environment:[context.environment?.signature,context.environment?.fetchedAt,context.environment?.start,context.environment?.end],prices:kind==='solar'?null:[context.prices?.fetchedAt,context.prices?.start,context.prices?.end],tariffs:kind==='solar'?null:context.tariffs.invoiceReference,forecast:archive?.cacheFingerprint??null});
 return calculated.get(key,{kind,project:context,proposal,archive});}
function householdResult(proposal){return cachedCalculation('household',proposal);}


