 const points=view.points,labels=points.map(p=>view.level==='year'?monthLabel(p.key):view.level==='month'?String(Number(p.key.slice(8))):localStamp(p.key).slice(11,16)),inspection=node('div',undefined,'hour-calculation');const inspect=i=>{const r=view.rows[i];inspection.replaceChildren(node('h3',r.time.slice(0,16)+' UTC'),node('p',estimatedTimes.has(new Date(Math.floor(Date.parse(r.time)/3600000)*3600000).toISOString())?'Estimated consumption: previous-year profile, invoice-calibrated.':'Measured Greenely consumption.','small'),node('p',`Household ${number(r.demand,3)} kWh; solar ${number(r.solarKwh,3)} kWh. Direct solar ${number(r.directSolarKwh,3)} kWh.${hasBattery?` Battery to house ${number(r.dischargeKwh-(r.batteryExportKwh??0),3)} kWh.`:''}`),node('p',`Grid import ${number(r.gridImportKwh,3)} kWh × ${number(r.importPrice,4)} SEK/kWh = ${number(r.importExpense,3)} SEK. Export ${number(r.exportKwh,3)} kWh × ${number(r.spot,4)} = ${number(r.exportRevenue,3)} SEK.`),node('p',`baseline ${number(r.baselineCost,3)} − system ${number(r.systemCost,3)} = ${number(r.savings,3)} SEK saved.${hasBattery?` Battery export ${number(r.batteryExportKwh??0,3)} kWh. Stored energy ${number(r.startingSocKwh,3)} → ${number(r.socKwh,3)} kWh.`:''}`));};const drill=i=>view.level==='day'?inspect(i):navigate({page:'strategy',period:points[i].key});
