if(project.consumption&&referenceAligned(project)){const w=referenceWindow(project.tariffs.invoiceReference);ensureArchivedForecasts(new Date(w.start).toISOString(),new Date(w.end-3600000).toISOString());}

function maximumKey(proposal,id){return proposal.id+':'+id+':'+optimizationSignature(project,proposal)+':'+historyData.get(id)?.cacheFingerprint;}
function renderMaximum(){const box=$('maximum-results'),tabs=$('maximum-proposals');if(!box)return;box.replaceChildren();tabs.replaceChildren();const proposal=project.proposals.find(p=>p.id===(project.maximumProposalId||project.arbitrageProposalId))||project.proposals[0];if(!proposal)return;renderProposalSelect(tabs,proposal.id,id=>{project.maximumProposalId=id;save();renderMaximum();});if(historyLoading||!historyResults){box.append(simulationSkeleton('Loading the three historical years…'));return;}const id=selectedHistoryPeriod(),dataset=historyData.get(id);if(!dataset){box.append(node('p','Choose one of the three available reference years.','pending'));return;}for(const y of historyResults.periods){const current=historyResults.results.find(r=>r.period===y.id&&r.proposalId===proposal.id&&r.signature===optimizationSignature(project,proposal));if(!current&&historyData.has(y.id))ensureMaximum(proposal,historyData.get(y.id));}const matches=historyResults.results.filter(r=>r.signature===optimizationSignature(project,project.proposals.find(p=>p.id===r.proposalId)||proposal));box.append(groupedSavingsChart({groups:project.proposals.map(p=>({id:p.id,name:p.name,kind:proposalKind(p),rows:historyResults.periods.map(y=>{const r=matches.find(r=>r.period===y.id&&r.proposalId===p.id);return {period:y.id,label:y.id.slice(0,4)+'–'+y.id.slice(7),causal:r?.controller.savings??null,maximum:r?.perfect.savings??null};})})),onSelect:(proposalId,period)=>{project.maximumProposalId=proposalId;save();navigate({page:'maximum',period});}}),node('p','Historical consumption, weather and spot prices; reference invoice fees and energy tax reused by calendar month across all three years. This isolates year-to-year performance without inventing old contract prices. Causal comparison uses previous-day solar and past-week/day demand for every year.','small'));
 const key=maximumKey(proposal,id),cached=maximumCache.get(key);if(!cached){box.append(simulationSkeleton(maximumLoading.has(key)?'Calculating the optimal 15-minute dispatch…':'Simulation queued automatically…'));ensureMaximum(proposal,dataset);return;}if(cached.error){box.append(node('p',cached.error,'pending'));return;}const view=householdBreakdown(cached.perfect,currentPeriod()),controller=householdBreakdown(cached.controller,currentPeriod()),annual=/^\d{4}-\d{4}$/.test(currentPeriod());box.append(node('h2',`${number(view.savings,2)} SEK theoretical maximum ${annual?'yearly ':''}savings`),node('p',`${number(controller.savings,2)} SEK from the causal comparison controller; ${number(view.savings-controller.savings,2)} SEK difference. ${view.rows.length} simulated intervals in this view.`),node('p',`${dataset.period.hours} hours in the full year (${dataset.period.estimatedHours} estimated readings). Solver: ${cached.perfect.status}; objective minimizes import costs minus export revenue . Savings are relative to your already-smart-charged household baseline.`,'small'));
 const cards=node('div',undefined,'roof-calculations');for(const [label,value]of [['Without solar/battery',view.baselineCost],['With perfect foresight',view.systemCost]]){const card=node('div',undefined,'roof-calculation');card.append(node('h3',label),node('strong',number(value,2)+' SEK'));cards.append(card);}box.append(cards);
 const points=view.points,comparison=new Map(controller.points.map(p=>[p.key,p])),pointLabels=points.map(p=>view.level==='year'?monthLabel(p.key):view.level==='month'?String(Number(p.key.slice(8))):localStamp(p.key).slice(11,16)),inspection=node('div',undefined,'hour-calculation');const inspect=i=>{const r=view.rows[i];inspection.replaceChildren(node('h3',r.time.slice(0,16)+' UTC'),node('p',`Consumption ${number(r.demand,3)} kWh; solar ${number(r.solarKwh,3)} kWh; curtailment ${number(r.curtailedKwh,3)} kWh.`),node('p',`Grid charging ${number(r.gridChargeKwh,3)} kWh; solar charging ${number(r.solarChargeKwh,3)} kWh; battery discharge ${number(r.dischargeKwh,3)} kWh (${number(r.batteryExportKwh,3)} exported). State ${number(r.startingSocKwh,3)} → ${number(r.socKwh,3)} kWh.`),node('p',`Import ${number(r.importExpense,3)} SEK − export ${number(r.exportRevenue,3)} SEK = ${number(r.systemCost,3)} SEK system cost. Savings ${number(r.savings,3)} SEK.`));};const drill=i=>view.level==='day'?inspect(i):navigate({page:'maximum',period:points[i].key});box.append(timeChart({title:'Savings with perfect foresight vs causal control',labels:pointLabels,unit:'SEK',rightUnit:'SEK/kWh',series:[{name:'Perfect foresight',values:points.map(p=>p.savings)},{name:'Causal controller',values:points.map(p=>comparison.get(p.key)?.savings??null)},{name:'Mean SE4 spot',axis:'right',decimals:4,values:points.map(p=>p.spot)}],onSelect:drill}),timeChart({title:'Perfect-foresight energy flows',labels:pointLabels,unit:'kWh',series:[{name:'Grid charging',values:points.map(p=>p.gridChargeKwh)},{name:'Solar charging',values:points.map(p=>p.solarChargeKwh)},{name:'Battery discharge',values:points.map(p=>p.dischargeKwh)}],onSelect:drill}));if(view.level==='day'){inspect(0);box.append(inspection);}const limits=node('details');limits.append(node('summary','What this maximum assumes'),node('p','Complete future knowledge of consumption, solar and prices. Battery exports and PV curtailment allowed, with no support-service income. Battery capacity, reserve, conversion losses, charge/discharge power, shared inverter output and approximate 20 A connection headroom are enforced. Simultaneous battery charge/discharge and simultaneous grid import/export are forbidden. Each year starts at minimum reserve; ending inventory receives no cash credit.','small'),node('p','This is a proven optimum within the 15-minute mathematical model, not an absolute physical or future-income guarantee. Subhourly peaks, phase imbalance, unknown export-contract adjustments, network feed-in credit, panel-level electrical shading effects, snow coverage, degradation and extra subscription fees remain outside the model. Both controllers allow battery exports under the same assumed spot compensation. Hourly household and solar energy is spread uniformly across quarters.','pending'));box.append(limits);}
function simulationSkeleton(message){const box=node('div',undefined,'simulation-skeleton');box.setAttribute('role','status');box.setAttribute('aria-busy','true');const status=node('p',message,'small simulation-status'),spinner=node('span',undefined,'simulation-spinner');spinner.setAttribute('aria-hidden','true');status.prepend(spinner);box.append(status);for(const cls of ['skeleton-title','skeleton-summary','skeleton-graph'])box.append(node('div',undefined,'skeleton-block '+cls));return box;}
function scheduleAutomaticSimulations(){clearTimeout(autoSimulationTimer);autoSimulationTimer=setTimeout(runAutomaticSimulations,250);}
async function runAutomaticSimulations(){
 if(autoSimulationRunning||historyLoading||!historyResults)return;autoSimulationRunning=true;
 try{while(true){const selectedId=project.maximumProposalId||project.arbitrageProposalId;const proposals=[...project.proposals].sort((a,b)=>(b.id===selectedId)-(a.id===selectedId));let task=null;for(const p of proposals){const periods=[...historyResults.periods].sort((a,b)=>(b.id===selectedHistoryPeriod())-(a.id===selectedHistoryPeriod()));for(const period of periods){const d=historyData.get(period.id),key=maximumKey(p,period.id);if(d&&!maximumCache.has(key)&&!maximumLoading.has(key)){task=[p,d];break;}}if(task)break;}if(!task)break;await ensureMaximum(...task);await new Promise(resolve=>setTimeout(resolve,0));}}
 finally{autoSimulationRunning=false;}
}
async function ensureMaximum(proposal,dataset){const key=maximumKey(proposal,dataset.period.id);if(maximumCache.has(key)||maximumLoading.has(key))return;maximumLoading.add(key);try{
 const signature=optimizationSignature(project,proposal),saved=historyResults?.results.find(r=>r.period===dataset.period.id&&r.proposalId===proposal.id&&r.signature===signature);let data=await loadSimulation(key).catch(()=>null);
 if(!data&&saved?.dispatchPath){const response=await fetch('./'+saved.dispatchPath);if(!response.ok)throw Error('Saved optimal dispatch could not be loaded.');data=await response.json();if(data.signature!==signature)throw Error('Saved optimum inputs differ.');}
 if(!data)data=await runOptimizer(null,proposal,dataset);
 maximumCache.set(key,data);await storeSimulation(key,data).catch(()=>{});
 if(optimizationSignature(project,proposal)===signature){historyResults.results=historyResults.results.filter(r=>!(r.period===dataset.period.id&&r.proposalId===proposal.id));historyResults.results.push({period:dataset.period.id,proposalId:proposal.id,signature,controller:resultSummary(data.controller,dataset.period.id),perfect:resultSummary(data.perfect,dataset.period.id)});}
 }catch(e){maximumCache.set(key,{error:e.message});}finally{maximumLoading.delete(key);if(visiblePage==='maximum')renderMaximum();}}

function runOptimizer(input,proposal,dataset=null){if(!optimizerWorker){optimizerWorker=new Worker('./perfect-worker.js?v=cash-no-wear',{type:'module'});optimizerWorker.onmessage=({data})=>{const request=optimizerRequests.get(data.id);if(!request)return;optimizerRequests.delete(data.id);if(data.error)request.reject(Error(data.error));else request.resolve(data.result);};optimizerWorker.onerror=e=>{for(const request of optimizerRequests.values())request.reject(Error(e.message||'Optimizer worker failed.'));optimizerRequests.clear();};}return new Promise((resolve,reject)=>{const id=++optimizerSequence;optimizerRequests.set(id,{resolve,reject});optimizerWorker.postMessage({id,input,dataset,project:dataset?project:undefined,proposal:dataset?proposal:undefined,settings:batterySettings(project,proposal),inverterKw:proposal.inverterKw,options:{maxGridKw:13.8}});});}
async function loadHistory(){try{const response=await fetch('./data/history/results.json',{cache:'no-store'});if(!response.ok)throw Error('Historical results not available.');historyResults=await response.json();await Promise.all(historyResults.periods.map(async p=>{const r=await fetch('./data/history/'+p.id+'.json',{cache:'no-store'});if(!r.ok)throw Error('Historical source year unavailable.');const source=await r.text(),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(source)),dataset=JSON.parse(source);dataset.cacheFingerprint=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');historyData.set(p.id,dataset);}));const reference=historyData.get('2025-2026');if(reference?.environment.signature===environmentSignature(project.house)&&project.environment?.signature!==reference.environment.signature){project.environment=reference.environment;project.prices=reference.prices;save();}historyLoading=false;scheduleAutomaticSimulations();renderDateNavigation();if(visiblePage==='detail'&&selected)updateDetail();else if(visiblePage==='maximum')renderMaximum();else if(visiblePage==='strategy')renderArbitrage();else if(visiblePage==='roi')renderRoi();else if(visiblePage==='compare')renderCompare();else if(visiblePage==='data'){renderConsumption();renderEnvironment();renderPrices();renderInvoices();}}catch(e){historyLoading=false;historyLoadError=e.message;if(visiblePage==='compare')renderCompare();if(visiblePage==='maximum')$('maximum-results').textContent=e.message;}}
loadHistory();

function renderUsageExports(){const box=$('usage-exports');box.replaceChildren();if(!rawUsageData){box.append(node('p','Raw consumption data is unavailable.','pending'));return;}box.append(node('p','Original hourly readings for each October–September year. Missing readings remain blank; simulated gap fills are excluded. CSV includes UTC timestamps, local timestamps, kWh and source row numbers.','small'));for(const year of [2023,2024,2025]){const rows=rawUsageYear(rawUsageData.rows,year),missing=rows.filter(r=>!Number.isFinite(r.kwh)).length,card=node('div',undefined,'content-card');card.append(node('h2',`${year}–${String(year+1).slice(2)}`),node('p',`1 October ${year} – 30 September ${year+1} · ${rows.length.toLocaleString('en-GB')} hourly readings · ${missing} missing`,'small'),button('Download CSV',()=>{const url=URL.createObjectURL(new Blob([usageCsv(rows)],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`household-usage-${year}-${year+1}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);},'primary'));box.append(card);}}
